  <script>
    // ===== INITIALIZE ICONS =====
    lucide.createIcons();

    // ===== MOBILE MENU =====
    function toggleMobileMenu() {
      const overlay = document.getElementById('mobile-overlay');
      const drawer = document.getElementById('mobile-drawer');
      const isOpen = drawer.classList.contains('open');

      if (isOpen) {
        drawer.classList.remove('open');
        overlay.classList.remove('open');
        document.body.style.overflow = '';
      } else {
        drawer.classList.add('open');
        overlay.classList.add('open');
        document.body.style.overflow = 'hidden';
        // Re-initialize icons in drawer
        setTimeout(() => lucide.createIcons(), 50);
      }
    }

    // ===== SCROLL HELPERS =====
    function scrollToTop() {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
    function scrollToElement(id) {
      const el = document.getElementById(id);
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    // ===== SEARCH AUTOCOMPLETE =====
    const suggestions = [
      { label: 'Dentist', sub: 'Cleanings, fillings, oral health exams', icon: 'smile' },
      { label: 'Primary Care', sub: 'Annual checkups, sick visits, preventive care', icon: 'stethoscope' },
      { label: 'Dermatologist', sub: 'Skin conditions, acne, cosmetic consultations', icon: 'sparkles' },
      { label: 'Psychiatrist', sub: 'Mental health evaluations, medication management', icon: 'brain' },
      { label: 'Eye Doctor', sub: 'Vision exams, glasses prescriptions, eye health', icon: 'eye' },
      { label: 'Orthopedic Surgeon', sub: 'Joint pain, fractures, sports injuries', icon: 'bone' },
      { label: 'Back pain', sub: 'Spine specialists and physical therapists', icon: 'activity' },
      { label: 'Dr. Sarah Chen', sub: 'Dermatologist · New York, NY · 4.9 ★', icon: 'user' },
      { label: 'Dr. Michael Park', sub: 'Primary Care · Chicago, IL · 4.8 ★', icon: 'user' },
      { label: 'Dr. James Wilson', sub: 'Dentist · Austin, TX · 4.7 ★', icon: 'user' },
      { label: 'Cardiologist', sub: 'Heart health, blood pressure, cardiovascular care', icon: 'heart' },
      { label: 'Pediatrician', sub: 'Children\'s health, vaccinations, development', icon: 'baby' },
      { label: 'OB-GYN', sub: 'Women\'s health, pregnancy, annual exams', icon: 'users' },
      { label: 'Allergist', sub: 'Allergies, asthma, immunology', icon: 'wind' },
      { label: 'Physical Therapist', sub: 'Rehabilitation, injury recovery, mobility', icon: 'activity' },
    ];

    let activeIndex = -1;

    function handleAutocomplete(query) {
      const dropdown = document.getElementById('autocomplete-dropdown');
      activeIndex = -1;

      if (!query || query.trim().length === 0) {
        dropdown.classList.remove('active');
        dropdown.innerHTML = '';
        return;
      }

      const q = query.toLowerCase().trim();
      const filtered = suggestions.filter(s =>
        s.label.toLowerCase().includes(q) || (s.sub && s.sub.toLowerCase().includes(q))
      );

      if (filtered.length === 0) {
        dropdown.innerHTML = '<div class="p-4 text-sm text-gray-500 text-center">No results found</div>';
        dropdown.classList.add('active');
        return;
      }

      dropdown.innerHTML = filtered.map((s, i) => `
        <div class="autocomplete-item${i === activeIndex ? ' active' : ''}"
             onmousedown="selectSuggestion('${s.label.replace(/'/g, "\\'")}')"
             onmouseenter="setActiveIndex(${i})">
          <div class="ac-icon"><i data-lucide="${s.icon}" class="w-5 h-5"></i></div>
          <div>
            <div class="ac-text">${s.label}</div>
            <div class="ac-sub">${s.sub}</div>
          </div>
        </div>
      `).join('');

      dropdown.classList.add('active');
      lucide.createIcons();
    }

    function setActiveIndex(idx) {
      activeIndex = idx;
      const items = document.querySelectorAll('.autocomplete-item');
      items.forEach((item, i) => item.classList.toggle('active', i === idx));
    }

    function handleAutocompleteKey(e) {
      const dropdown = document.getElementById('autocomplete-dropdown');
      if (!dropdown.classList.contains('active')) return;

      const items = dropdown.querySelectorAll('.autocomplete-item');
      if (items.length === 0) return;

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        activeIndex = Math.min(activeIndex + 1, items.length - 1);
        setActiveIndex(activeIndex);
        items[activeIndex]?.scrollIntoView({ block: 'nearest' });
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        activeIndex = Math.max(activeIndex - 1, 0);
        setActiveIndex(activeIndex);
        items[activeIndex]?.scrollIntoView({ block: 'nearest' });
      } else if (e.key === 'Enter') {
        e.preventDefault();
        if (activeIndex >= 0 && items[activeIndex]) {
          items[activeIndex].click();
        }
      } else if (e.key === 'Escape') {
        dropdown.classList.remove('active');
        activeIndex = -1;
      }
    }

    function selectSuggestion(value) {
      document.getElementById('search-specialty').value = value;
      document.getElementById('autocomplete-dropdown').classList.remove('active');
      activeIndex = -1;
      // Auto-focus location
      document.getElementById('search-location').focus();
    }

    // Close autocomplete on outside click
    document.addEventListener('click', function(e) {
      const wrapper = document.querySelector('.autocomplete-wrapper');
      if (wrapper && !wrapper.contains(e.target)) {
        document.getElementById('autocomplete-dropdown').classList.remove('active');
        activeIndex = -1;
      }
    });

    // ===== SEARCH HANDLER =====
    function handleSearch(e) {
      e.preventDefault();
      const specialty = document.getElementById('search-specialty').value.trim();
      const location = document.getElementById('search-location').value.trim();
      const insurance = document.getElementById('search-insurance').value;

      let msg = 'Searching';
      if (specialty) msg += ` for "${specialty}"`;
      if (location) msg += ` near ${location}`;
      if (insurance) msg += ` (${document.getElementById('search-insurance').selectedOptions[0].text})`;
      msg += '...';

      showToast(msg);
      document.getElementById('autocomplete-dropdown').classList.remove('active');
    }

    function searchSpecialty(specialty) {
      document.getElementById('search-specialty').value = specialty;
      showToast(`Browsing ${specialty} providers near you...`);
      // Scroll to top search bar
      document.querySelector('.hero-pattern').scrollIntoView({ behavior: 'smooth', block: 'start' });
      // Focus the search
      setTimeout(() => document.getElementById('search-specialty').focus(), 500);
    }

    // ===== LOCATION DETECTION =====
    function detectLocation() {
      const locationInput = document.getElementById('search-location');
      if (navigator.geolocation) {
        showToast('Detecting your location...');
        navigator.geolocation.getCurrentPosition(
          () => {
            locationInput.value = 'Current Location';
            locationInput.style.color = '#1B1464';
            showToast('Location detected!');
            setTimeout(() => { locationInput.style.color = ''; }, 3000);
          },
          () => {
            showToast('Could not detect location. Please enter manually.');
          }
        );
      } else {
        showToast('Geolocation not supported by your browser.');
      }
    }

    // ===== TOAST =====
    function showToast(message) {
      const toast = document.getElementById('toast');
      toast.textContent = message;
      toast.classList.add('show');
      clearTimeout(toast._timeout);
      toast._timeout = setTimeout(() => {
        toast.classList.remove('show');
      }, 2500);
